xml.Script:
        Colors[ 0] := 'EE0000'; // Red
        Colors[ 1] := 'FF800A'; // Orange
        Colors[ 2] := 'FFFF00'; // Yellow
        Colors[ 3] := '00AA00'; // Green
        Colors[ 4] := '0033EE'; // Blue
        clWhite := 'FFFFFF';
        clCream := 'FFFFAA';

        R := 0.5;
        include 'Figures\Scripts\Dodecahedron_Coordinates.inc';

        H := R * 0.915;

        D := R * sqrt((5 + 2 * sqrt(5)) / 20);
        D2 := D * 1.125;

        N := 40;
        NAngle := 2 * Pi / N;
        for i := 0 to N - 1 do begin
            x[i] := R * cos(NAngle * (i + 6));
            y[i] := R * sin(NAngle * (i + 6));
        end;

        function FromTo(iFrom, iTo);
        begin
            Result := IntToStr(iFrom);
            for i := iFrom + 1 to iTo do
                Result := Result + ';' + IntToStr(i);
            for i := iFrom - 1 downto iTo do
                Result := Result + ';' + IntToStr(i);
        end;

Macro.Script:
i1 := i mod N;
i2 := (i + 1) mod N;
Inc(i);
